import { Show, type Incoming } from "@barqjs/core";
import { atomsIn } from "@barqjs/css";

import "../theme/layers.ts";
import { uiVariants } from "../lib/atoms.ts";
import type { UiProps } from "../lib/props.ts";
import { uiProps } from "../lib/slot.ts";

export type BadgeVariant = "default" | "secondary" | "destructive" | "outline" | "ghost" | "link";

/**
 * The classes, for a badge you render yourself.
 *
 * ```tsx
 * <button type="button" class={badgeVariants({ variant: "outline" })}>Draft</button>
 * ```
 */
export const badgeVariants = uiVariants({
  base: atomsIn("barq.ui", {
    display: "inline-flex",
    width: "fit-content",
    flexShrink: "0",
    alignItems: "center",
    justifyContent: "center",
    gap: "var(--spacing)",
    overflow: "hidden",
    borderRadius: "calc(infinity * 1px)",
    borderStyle: "var(--ui-border-style)",
    borderWidth: "1px",
    borderColor: "transparent",
    paddingInline: "calc(var(--spacing) * 2)",
    paddingBlock: "calc(var(--spacing) * 0.5)",
    fontSize: "var(--text-xs)",
    lineHeight: "var(--ui-leading, var(--text-xs--line-height))",
    "--ui-font-weight": "var(--font-weight-medium)",
    fontWeight: "var(--font-weight-medium)",
    whiteSpace: "nowrap",
    transitionProperty: "color, box-shadow",
    transitionTimingFunction: "var(--ui-ease, var(--default-transition-timing-function))",
    transitionDuration: "var(--ui-duration, var(--default-transition-duration))",
    ":focus-visible": {
      borderColor: "var(--ring)",
      "--ui-ring-shadow":
        "var(--ui-ring-inset,) 0 0 0 calc(3px + var(--ui-ring-offset-width)) var(--ui-ring-color, currentcolor)",
      boxShadow:
        "var(--ui-inset-shadow), var(--ui-inset-ring-shadow), var(--ui-ring-offset-shadow), var(--ui-ring-shadow), var(--ui-shadow)",
      "--ui-ring-color": "var(--ring)",
      "@supports (color: color-mix(in lab, red, red))": {
        "--ui-ring-color": "color-mix(in oklab, var(--ring) 50%, transparent)",
      },
    },
    '[aria-invalid="true"]': {
      borderColor: "var(--destructive)",
      "--ui-ring-color": "var(--destructive)",
      "@supports (color: color-mix(in lab, red, red))": {
        "--ui-ring-color": "color-mix(in oklab, var(--destructive) 20%, transparent)",
      },
    },
    ':is(.dark *)[aria-invalid="true"]': {
      "--ui-ring-color": "var(--destructive)",
      "@supports (color: color-mix(in lab, red, red))": {
        "--ui-ring-color": "color-mix(in oklab, var(--destructive) 40%, transparent)",
      },
    },
    "& > svg": {
      pointerEvents: "none",
      width: "calc(var(--spacing) * 3)",
      height: "calc(var(--spacing) * 3)",
    },
  }),
  variants: {
    variant: {
      default: atomsIn("barq.ui", {
        backgroundColor: "var(--primary)",
        color: "var(--primary-foreground)",
        "@media (hover: hover)": {
          "a&:hover": {
            backgroundColor: "var(--primary)",
          },
          "@supports (color: color-mix(in lab, red, red))": {
            "a&:hover": {
              backgroundColor: "color-mix(in oklab, var(--primary) 90%, transparent)",
            },
          },
        },
      }),
      secondary: atomsIn("barq.ui", {
        backgroundColor: "var(--secondary)",
        color: "var(--secondary-foreground)",
        "@media (hover: hover)": {
          "a&:hover": {
            backgroundColor: "var(--secondary)",
          },
          "@supports (color: color-mix(in lab, red, red))": {
            "a&:hover": {
              backgroundColor: "color-mix(in oklab, var(--secondary) 90%, transparent)",
            },
          },
        },
      }),
      destructive: atomsIn("barq.ui", {
        backgroundColor: "var(--destructive)",
        color: "var(--color-white)",
        ":focus-visible": {
          "--ui-ring-color": "var(--destructive)",
          "@supports (color: color-mix(in lab, red, red))": {
            "--ui-ring-color": "color-mix(in oklab, var(--destructive) 20%, transparent)",
          },
        },
        ":is(.dark *)": {
          backgroundColor: "var(--destructive)",
          "@supports (color: color-mix(in lab, red, red))": {
            backgroundColor: "color-mix(in oklab, var(--destructive) 60%, transparent)",
          },
        },
        ":is(.dark *):focus-visible": {
          "--ui-ring-color": "var(--destructive)",
          "@supports (color: color-mix(in lab, red, red))": {
            "--ui-ring-color": "color-mix(in oklab, var(--destructive) 40%, transparent)",
          },
        },
        "@media (hover: hover)": {
          "a&:hover": {
            backgroundColor: "var(--destructive)",
          },
          "@supports (color: color-mix(in lab, red, red))": {
            "a&:hover": {
              backgroundColor: "color-mix(in oklab, var(--destructive) 90%, transparent)",
            },
          },
        },
      }),
      outline: atomsIn("barq.ui", {
        borderColor: "var(--border)",
        color: "var(--foreground)",
        "@media (hover: hover)": {
          "a&:hover": {
            backgroundColor: "var(--accent)",
            color: "var(--accent-foreground)",
          },
        },
      }),
      ghost: atomsIn("barq.ui", {
        "@media (hover: hover)": {
          "a&:hover": {
            backgroundColor: "var(--accent)",
            color: "var(--accent-foreground)",
          },
        },
      }),
      link: atomsIn("barq.ui", {
        color: "var(--primary)",
        textUnderlineOffset: "4px",
        "@media (hover: hover)": {
          "a&:hover": {
            textDecorationLine: "underline",
          },
        },
      }),
    },
  },
  defaults: { variant: "default" },
});

export interface BadgeProps extends UiProps {
  variant?: BadgeVariant;
  /** Renders an `<a>` instead of a `<span>`. The hover styles are written for it. */
  href?: string;
  target?: string;
  rel?: string;
}

/**
 * ```tsx
 * <Badge>New</Badge>
 * <Badge variant="destructive">Overdue</Badge>
 * <Badge variant="outline" href="/tags/rust">rust</Badge>
 * ```
 */
export function Badge(props: Incoming<BadgeProps>) {
  const className = (): string => badgeVariants({ variant: props.variant?.() });
  const shared = (): Record<string, unknown> => ({
    ...uiProps("badge", className, props),
    "data-variant": props.variant?.() ?? "default",
  });

  return (
    <Show
      when={props.href?.() !== undefined}
      fallback={<span {...shared()}>{props.children}</span>}
    >
      <a {...shared()} href={props.href?.()} target={props.target?.()} rel={props.rel?.()}>
        {props.children}
      </a>
    </Show>
  );
}
